function wrap(a) { return Math.atan2(Math.sin(a), Math.cos(a)); }
function clamp(v) { return Math.max(-1, Math.min(1, v)); }
function step(o, m) {
  m.n = (m.n || 0) + 1;
  if (o.carried) return { turn: 0, move: 0, fire: false, jump: true };
  if (o.hang) return { turn: 0, move: 0, fire: false, jump: m.n % 2 === 0 };
  if (o.rider) return { turn: m.n % 4 < 2 ? -1 : 1, move: 0, fire: false, jump: m.n % 3 === 0 };
  const g = o.goal;
  const near = o.foes.find(f => f.awake && f.d < 10);
  const fire = !!o.aim.hit && m.n % 2 === 0;
  const stuck = stuckTicks(o, m, 25);
  const slam = o.foes.some(f => f.st === 'slam' && f.d < 4);
  if (g.kind === 'ladder' || (g.kind === 'ladder-approach' && g.d < 2.5)) {
    const e = wrap(Math.PI - o.yaw);
    const ok = Math.abs(e) < 0.5;
    return { turn: clamp(e * 3), move: ok ? 1 : 0, fire, jump: slam };
  }
  if (g.kind === 'lift' && g.d < 1.2) return { turn: clamp(g.b * 2), move: 0, fire, jump: slam };
  const edge = o.drop.f < 1.5 && g.kind !== 'spring' && g.kind.indexOf('stairs') < 0 && g.kind !== 'crane-step';
  if (stuck && g.kind !== 'lift') return { turn: Math.sin(m.n * 0.7), move: edge ? 0 : 0.8, fire, jump: true };
  const move = Math.abs(g.b) < 1 && !edge ? 1 : 0;
  const hop = g.kind === 'crane-step' && g.d < 1.5 && o.ground;
  return { turn: clamp(g.b * 2), move, fire, jump: slam || hop };
}

// walk toward the goal marker, shoot whatever is in the aim band
// ladders: at the approach, face west (yaw PI) and push in; hanging/carried: jump out
function step(o, m) {
  const g = o.goal;
  if (o.carried || o.hang) return { turn: 0, move: 0, fire: false, jump: true };
  if (g.kind === 'ladder' || (g.kind === 'ladder-approach' && g.d < 2.5)) {
    const e = wrapA(Math.PI - o.yaw);
    return { turn: clampU(e * 3), move: Math.abs(e) < 0.5 ? 1 : 0, fire: !!o.aim.hit, jump: false };
  }
  const turn = Math.max(-1, Math.min(1, g.b * 2));
  return { turn, move: Math.abs(g.b) < 1 ? 1 : 0, fire: !!o.aim.hit, jump: false };
}

// Hybrid: A's brisk walking + ladder push; B's survival rules, boss spacing, stuck recovery.
function step(o, m) {
  const g = o.goal;
  m.n = (m.n || 0) + 1;
  const stuck = stuckTicks(o, m, 30);
  if (o.carried || o.hang) return { turn: 0, move: 0, fire: false, jump: true };
  if (o.rider) return { turn: m.n % 4 < 2 ? -1 : 1, move: 0, fire: false, jump: m.n % 2 === 0 };

  const boss = o.foes.find(f => f.k === 'boss' && f.awake);
  const hit = !!o.aim.hit || o.foes.some(f => f.awake && f.band);
  const fire = hit && (boss ? true : m.n % 5 < 3);
  const slam = o.foes.some(f => (f.st === 'slam' || f.st === 'windup') && f.d < 4.5) || shotDanger(o, 3, 0.5);
  const out = (turn, move, jump, use) => ({
    turn: clampU(turn), move: clampU(move), fire, jump: !!jump, use: !!use, sel: 0,
  });

  if (boss && boss.d < 14) {
    const ang = Math.atan2(boss.dy, boss.d);
    const wind = boss.d < 9 && /slam|wind|shock|stomp|charge|throw/.test(boss.st || '');
    const useNow = o.inv.length > 0 && m.n - (m.u || -99) > 25;
    if (useNow) m.u = m.n;
    let move = boss.d > 9 ? 0.8 : boss.d < 5 ? -0.6 : 0.3;
    if (!boss.band && Math.abs(ang) > 0.15 && boss.d < 12) move = -0.6;
    if (move > 0 && o.drop.f < 2) move = 0;
    if (move < 0 && o.drop.b !== undefined && o.drop.b < 2) move = 0;
    const weave = Math.floor(o.t / 3) % 2 ? 0.15 : -0.15;
    return out(steerTo(boss.b + weave, 2.5), move, wind || slam, useNow);
  }

  if (g.kind === 'ladder' || (g.kind === 'ladder-approach' && g.d < 2.5)) {
    const e = wrapA(Math.PI - o.yaw);
    return out(e * 3, Math.abs(e) < 0.5 ? 1 : 0, false);
  }
  if (g.kind === 'lift' && g.d < 1.2) return out(steerTo(g.b, 2.5), 0, slam);

  if (stuck) return out(Math.sin(m.n * 0.7), o.drop.f < 1.5 ? 0 : 0.8, true);

  const heal = o.hp < 55 ? o.items.find(i => i.k === 'juice' && i.d < 8) : null;
  const tb = heal ? heal.b : g.b;
  const crane = /crane/.test(g.kind);
  const climb = g.kind === 'crane-step' && g.d < 1.5 && o.ground && (g.stepY || 0) > o.y + 0.3;
  const edge = !crane && g.kind !== 'spring' && g.kind.indexOf('stairs') < 0 && o.drop.f < 1.5;
  const move = edge || Math.abs(tb) >= 1.3 ? 0 : Math.abs(tb) < 0.6 ? 1 : 0.6;
  return out(steerTo(tb, 2.5), move, climb || slam);
}

// special states first: carried/hang: jump; kitty on head: jump and shake;
// ladder: face west and push in; lift: stand still; otherwise creep (0.2) toward the goal,
// firing rarely, jumping over telegraphed attacks and crane-step gaps
function step(o, m) {
  const g = o.goal;
  m.n = (m.n || 0) + 1;
  if (o.carried) return { turn: 0, move: 0, fire: false, jump: true };
  if (o.hang) return { turn: 0, move: 0, fire: false, jump: true };
  if (o.rider) return { turn: m.n % 4 < 2 ? -1 : 1, move: 0, fire: false, jump: m.n % 2 === 0 };

  const stuck = stuckTicks(o, m, 30);
  const threat = o.foes.some(f => f.st === 'slam' && f.d < 5) || o.shots.some(s => !s.shootable && s.d < 3);
  const boss = o.foes.find(f => f.k === 'boss' && f.awake);
  // hold fire almost never: only at a close, hittable foe, every sixth tick; always at the boss
  const close = o.foes.some(f => f.awake && f.d < 3);
  const fire = !!o.aim.hit && (!!boss || (close && m.n % 30 === 0));

  if (boss) {
    const wave = boss.d < 14 && /slam|wind|shock|stomp/.test(boss.st || '');
    const mv = boss.d > 8 ? 0.2 : boss.d < 5 ? -0.2 : 0;
    return { turn: clampU(boss.b * 3), move: o.drop.f < 2 && mv > 0 ? 0 : mv, fire, jump: wave || threat };
  }

  // ladder: the lattice is only climbable facing west from the east; push in once aligned
  const lattice = g.kind === 'ladder' || (g.kind === 'ladder-approach' && g.d < 2.5);
  if (lattice) {
    const e = wrapA(Math.PI - o.yaw);
    return { turn: clampU(e * 3), move: Math.abs(e) < 0.5 ? 1 : 0, fire, jump: false };
  }

  // lift: stand still on it, it rises as long as you stand there
  if (g.kind === 'lift' && g.d < 1.2) return { turn: steerTo(g.b, 2), move: 0, fire, jump: threat };

  // stuck: no vertical progress for ~3 s, so hop and wander
  if (stuck) return { turn: Math.sin(m.n * 0.7), move: o.drop.f < 1.5 ? 0 : 0.2, fire, jump: true };

  const ramp = /stairs|spring|crane/.test(g.kind);
  const edge = o.drop.f < 1.5 && !ramp;
  // grab nearby juice when hurt
  const heal = o.hp < 60 ? o.items.find(i => i.k === 'juice' && i.d < 6) : undefined;
  const tb = heal ? heal.b : g.b;
  // spring: walk onto the pad and let it throw you; crane-step: hop across gaps
  const hop = threat || (g.kind === 'crane-step' && g.d < 1.5 && o.ground);
  const walk = edge ? 0 : Math.abs(tb) < 1.2 ? 0.35 : 0.15;
  return { turn: steerTo(tb, 2), move: walk, fire, jump: hop };
}

// slow, deliberate climber: holds fire only at the boss or a foe winding up an attack;
// rider: shake and jump; carried/hang: jump out; boss: circle and shoot; ladder: face west and push in;
// lift: stand still; stuck: hop and wander; otherwise steer to the goal at about a third pace, grabbing juice when hurt
function step(o, m) {
  const g = o.goal;
  m.n = (m.n || 0) + 1;
  if (o.carried || o.hang) return { turn: 0, move: 0, fire: false, jump: true };
  if (o.rider) return { turn: m.n % 4 < 2 ? -1 : 1, move: 0, fire: false, jump: m.n % 2 === 0 };

  const ramp = /stairs|spring|crane/.test(g.kind);
  const edge = o.drop.f < 1.5 && !ramp;
  const stuck = stuckTicks(o, m, 25);
  const boss = o.foes.find(f => f.k === 'boss' && f.awake);
  // shoot only at the boss, or at a close foe that is telegraphing an attack
  const winding = o.foes.some(f => f.awake && f.band && f.d < 6 && /wind|rev|slam|throw|dive|crouch/.test(f.st || ''));
  const fire = !!o.aim.hit && (!!boss || winding);
  const near = o.foes.filter(f => f.awake && f.d < 10);
  const threat = o.foes.some(f => f.st === 'slam' && f.d < 5) || o.shots.some(s => s.d < 3);
  // use the selected pickup when outnumbered or facing the boss, at most every 20 ticks
  const use = !!((boss || near.length >= 2) && o.inv.length > 0 && m.n - (m.u || -99) > 20);
  if (use) m.u = m.n;
  const out = (turn, move, jump) => ({ turn: clampU(turn), move: clampU(move), jump, fire, use, sel: 0 });

  if (boss) {
    // circle at range 6-9 with a sideways arc; shoot when in band; jump telegraphed shockwaves
    const arc = Math.floor(o.t / 3) % 2 ? 0.35 : -0.35;
    const want = boss.d < 6 ? -0.8 : boss.d > 9 ? 0.8 : 0.4;
    const wave = boss.d < 14 && /slam|wind|shock|stomp/.test(boss.st || '');
    return out(boss.b * 3 + arc, want > 0 && o.drop.f < 2 ? 0 : want, wave || threat);
  }

