  // slow pace: about a third of full speed when roughly facing the goal, a crawl on turns
  const walk = !edge && Math.abs(tb) < 1.2 ? 0.35 : 0.1;
  return out(tb * 2.5, edge ? 0 : walk, climb || threat);
