  const climb = g.kind === 'crane-step' && g.d < 1.5 && o.ground;
  const walk = !edge && Math.abs(tb) < 1.2 ? 1 : 0.6;
  return out(tb * 2, edge ? 0 : walk, climb || threat);
}

